SELECT MAPPING_STATUS, ACCURACY, CONFIRM_CLS_TEXT, ACODE, SAUPJ, SITE, REFNO2, GROUP_KEY, MAPPING_TYPE ,TOTAL_PRIN_AMOUNT , TOTAL_TAX, C_CHARGETOTAL , C_TAXTOTAL, ACCNO, ACCSEQ, ISSUE_DATE, CURRENCY ,PRIN_AMOUNT, CREDIT, ACODENM, REMARK, A01_REGNO, A01_CUSTOMERNM, KEP_DEPT_CD, KEP_DEPT_NM, A01_CCODE ,CT01_NAME, A01_REFNO2, ENTRY_DATE, CREATE_DATE, EMPLOYEE, USER_NM, ISSUE_ID, IP_NAME ,ISSUE_DT, TYPE_CODE, CHARGETOTAL, TAXTOTAL, ASP_CODE, SU_EMAIL, SU_PERSNAME, IP_EMAIL1, IP_PERSNAME1 ,DESC_TEXT1, AMEND_CODE, M_STATUS, CONFIRM_CLS, KEP_EMAIL, RNK, IMAGE_KEY, IMAGE_KEY_YN FROM ( SELECT DECODE(B.MAPPING_STATUS,NULL,'미매핑','A','자동매핑','O','수동매핑','E','수기매핑') AS MAPPING_STATUS ,DECODE(B.ACCURACY,'Y','금액일치','N','금액불일치','') AS ACCURACY ,DECODE(A.CONFIRM_CLS,'Y','확정','미확정') CONFIRM_CLS_TEXT ,DECODE(A.ACODE,'1114805','매입','2112605','매출') AS ACODE ,A.SAUPJ AS SAUPJ ,DECODE(SUBSTR(A.REFNO2,1,2),'TP','건설유통','TS','건설유통','AP','구매대행','AR','구매대행','일반') AS SITE ,DECODE(SUBSTR(A.REFNO2,1,2),'TP','건설유통매입','TS','건설유통매출','AP','구매대행매입','AR','구매대행매출') AS REFNO2 ,NVL(B.GROUP_KEY,A.ACCNO||A.ACCSEQ) GROUP_KEY ,B.MAPPING_TYPE ,SUM(A.PRIN_AMOUNT) OVER (PARTITION BY NVL(B.GROUP_KEY,A.ACCNO||A.ACCSEQ) ) TOTAL_PRIN_AMOUNT ,SUM(DECODE(A.ACODE,'2112605',CREDIT, '1114805',DEBIT)) OVER (PARTITION BY NVL(B.GROUP_KEY,A.ACCNO||A.ACCSEQ) ) TOTAL_TAX ,SUM(C.CHARGETOTAL) OVER (PARTITION BY NVL(B.GROUP_KEY,A.ACCNO||A.ACCSEQ) ) C_CHARGETOTAL ,SUM(C.TAXTOTAL) OVER (PARTITION BY NVL(B.GROUP_KEY,A.ACCNO||A.ACCSEQ) ) C_TAXTOTAL ,A.ACCNO ,A.ACCSEQ ,A.ISSUE_DATE ,A.CURRENCY ,A.PRIN_AMOUNT ,DECODE(A.ACODE,'2112605',CREDIT, '1114805',DEBIT) CREDIT ,A.ACODENM ,A.REMARK ,A.A01_REGNO ,A.A01_CUSTOMERNM ,D.CODE KEP_DEPT_CD ,D.TEXT2 KEP_DEPT_NM ,A.A01_CCODE ,A.CT01_NAME ,A.REFNO2 A01_REFNO2 ,A.ENTRY_DATE ,A.CREATE_DATE ,E.USER_ID EMPLOYEE ,E.USER_NAME_LOC USER_NM ,DECODE(B.MAPPING_TYPE,'NN',B.ISSUE_ID||'외 다수건',B.ISSUE_ID) ISSUE_ID ,DECODE(C.ARAP,'AP',C.SU_NAME,'AR',IP_NAME) AS IP_NAME ,C.ISSUE_DT ,DECODE(C.TYPE_CODE,'0101','일반 세금계산서' ,'0102','영세율 세금계산서' ,'0201', '수정 일반 세금계산서' ,'0202','수정 영세율 세금계산서' ,'0301','일반 계산서') TYPE_CODE ,C.CHARGETOTAL ,C.TAXTOTAL ,(SELECT COD1.TEXT1 FROM ICOMCOD1 COD1 WHERE COD1.TYPE='TX09' AND COD1.CODE=C.ASP_CODE AND ROWNUM=1 ) ASP_CODE ,C.SU_EMAIL ,C.SU_PERSNAME ,C.IP_EMAIL1 ,C.IP_PERSNAME1 ,C.DESC_TEXT1 ,C.AMEND_CODE ,B.STATUS AS M_STATUS ,A.CONFIRM_CLS ,E.EMAIL KEP_EMAIL ,DECODE(B.MAPPING_TYPE, NULL,1,'11',1,'1N',1,'N1',1, RANK() OVER ( PARTITION BY B.GROUP_KEY||B.ACCNO||B.ACCSEQ, B.MAPPING_TYPE ORDER BY B.ACCNO||B.ACCSEQ||B.ISSUE_ID)) RNK ,B.IMAGE_KEY ,DECODE(B.IMAGE_KEY,NULL,'2','3') AS IMAGE_KEY_YN FROM TACCOUNT_TAX_IF A, TACCOUNT_TAX_MAPPING B, KEPTAX.ZDTV3T_NTS C, ICOMCOD1 D, ICOMLUSR E WHERE A.ACCNO = B.ACCNO(+) AND A.ACCSEQ = B.ACCSEQ(+) AND B.ISSUE_ID = C.ISSUE_ID(+) AND B.STATUS(+) = 'C' AND E.COM_CODE='KRKORE0001' AND E.OFFICE_YN IS NULL AND E.LEGACY_USER_ID IS NOT NULL AND A.ISSUE_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.A01_CCODE=D.TEXT1 AND D.TYPE='TX06' AND ( CASE WHEN SUBSTR(A.REFNO2,1,2) = 'AR' THEN (SELECT ARDT.ADD_USER_ID FROM KEPTARDT ARDT WHERE ARDT.TAX_BILL_NO=A.REFNO2 AND ROWNUM=1) WHEN SUBSTR(A.REFNO2,1,2) = 'AP' THEN (SELECT APDT.ADD_USER_ID FROM KEPTAPDT APDT WHERE APDT.TAX_BILL_NO=A.REFNO2 AND ROWNUM=1 ) WHEN SUBSTR(A.REFNO2,1,2) = 'TS' THEN (SELECT APDT.RESGTR_ID FROM KEPCMCL01@KEPCON APDT WHERE APDT.SLS_TAX_BILL_NO=A.REFNO2 AND ROWNUM=1) WHEN SUBSTR(A.REFNO2,1,2) = 'TP' THEN (SELECT APDT.RESGTR_ID FROM KEPCMCL03@KEPCON APDT WHERE APDT.PRCHS_TAX_BILL_NO=A.REFNO2 AND ROWNUM=1) WHEN A.REFNO2 IS NULL THEN (SELECT LUSR.USER_ID FROM ICOMLUSR LUSR WHERE LUSR.COM_CODE='KRKORE0001' AND LUSR.OFFICE_YN IS NULL AND LUSR.LEGACY_USER_ID=A.EMPLOYEE AND ROWNUM=1) END) = E.USER_ID
AND A.ACODE = #{st_a_code}
AND SUBSTR(A.REFNO2,1,2) IN ('AR','AP')
AND SUBSTR(A.REFNO2,1,2) IN ('TP','TS')
AND A.REFNO2 IS NULL
AND A.STATUS in ( 'C' ,'R')
AND A.STATUS = 'D'
AND A.ACCNO LIKE #{st_accno}||'%'
AND C.ISSUE_ID LIKE #{st_issue_id}||'%'
AND A.A01_REGNO LIKE #{st_a01_regno}||'%'
AND A.A01_CUSTOMERNM LIKE #{st_a01_customer_nm}||'%'
AND D.CODE = #{st_user_dept}
AND E.USER_ID = #{st_add_user_id}
AND A.REFNO2 = #{st_tax_bill_no}
AND B.GROUP_KEY = #{st_group_key}
AND C.ISSUE_ID = #{st_issue_id}
AND A.CONFIRM_CLS = 'Y'
AND A.CONFIRM_CLS IS NULL
AND B.ACCURACY = #{st_accuracy}
AND B.MAPPING_TYPE = #{st_mapping_type}
AND B.MAPPING_STATUS IN ('A','O','E')
AND B.MAPPING_STATUS IS NULL
AND B.MAPPING_STATUS = 'A'
AND B.MAPPING_STATUS = 'B'
AND B.MAPPING_STATUS = 'O'
AND B.MAPPING_STATUS = 'E'
) WHERE RNK = 1 ORDER BY MAPPING_STATUS, ACODE, ACCNO, ACCSEQ, ISSUE_ID

mapper.update:
