SELECT ISSUE_ID, ARAP, ARAP_CODE, ISSUE_DT, ISSUE_DATE, ASP_CODE, TYPE_CODE, PURP_CODE, AMEND_CODE, ISSUE_ID_OLD, DESC_TEXT1, SU_ID, SU_MIN, SU_NAME, SU_REPRES, SU_ADDR, SU_BUSTYPE, SU_INDTYPE, SU_DEPTNAME, SU_PERSNAME, SU_TELNO, SU_HPNO, SU_EMAIL, IP_TYPECODE, IP_ID, IP_MIN, IP_NAME, IP_REPRES, IP_ADDR, IP_BUSTYPE, IP_INDTYPE, IP_DEPTNAME1, IP_PERSNAME1, IP_TELNO1, IP_HPNO1, IP_EMAIL1, IP_DEPTNAME2, IP_PERSNAME2, IP_TELNO2, IP_HPNO2, IP_EMAIL2, CHARGETOTAL, TAXTOTAL, GRANDTOTAL, ERDAT, ERZET, ERNAM, TRANS_DATE, ACCNO, ACCSEQ, USER_ID, USER_NAME_LOC, DEPARTMENT, NTS_GROUP_KEY, MAP_ISSUE_ID FROM ( SELECT NTS.ISSUE_ID ,DECODE(NTS.ARAP,'AR','매출','매입') ARAP ,NTS.ARAP AS ARAP_CODE ,NTS.ISSUE_DT ,NTS.ISSUE_DATE ,(SELECT COD1.TEXT1 FROM ICOMCOD1 COD1 WHERE COD1.TYPE='TX09' AND COD1.CODE=NTS.ASP_CODE AND ROWNUM=1 ) ASP_CODE ,DECODE(NTS.TYPE_CODE,'0101','일반 세금계산서' ,'0102','영세율 세금계산서' ,'0201', '수정 일반 세금계산서' ,'0202','수정 영세율 세금계산서' ,'0301','일반 계산서')TYPE_CODE ,(SELECT COD1.TEXT1 FROM ICOMCOD1 COD1 WHERE COD1.TYPE='TX10' AND COD1.CODE=NTS.PURP_CODE ) PURP_CODE ,(SELECT COD1.TEXT1 FROM ICOMCOD1 COD1 WHERE COD1.TYPE='TX14' AND COD1.CODE=NTS.AMEND_CODE ) AMEND_CODE ,NTS.ISSUE_ID_OLD ,NTS.DESC_TEXT1 ,NTS.SU_ID ,NTS.SU_MIN ,NTS.SU_NAME ,NTS.SU_REPRES ,NTS.SU_ADDR ,NTS.SU_BUSTYPE ,NTS.SU_INDTYPE ,NTS.SU_DEPTNAME ,NTS.SU_PERSNAME ,NTS.SU_TELNO ,NTS.SU_HPNO ,NTS.SU_EMAIL ,NTS.IP_TYPECODE ,NTS.IP_ID ,NTS.IP_MIN ,NTS.IP_NAME ,NTS.IP_REPRES ,NTS.IP_ADDR ,NTS.IP_BUSTYPE ,NTS.IP_INDTYPE ,NTS.IP_DEPTNAME1 ,NTS.IP_PERSNAME1 ,NTS.IP_TELNO1 ,NTS.IP_HPNO1 ,NTS.IP_EMAIL1 ,NTS.IP_DEPTNAME2 ,NTS.IP_PERSNAME2 ,NTS.IP_TELNO2 ,NTS.IP_HPNO2 ,NTS.IP_EMAIL2 ,NTS.CHARGETOTAL ,NTS.TAXTOTAL ,NTS.GRANDTOTAL ,NTS.ERDAT ,NTS.ERZET ,NTS.ERNAM ,NTS.TRANS_DATE ,MAP.ACCNO ,MAP.ACCSEQ ,LUSR.USER_ID ,LUSR.USER_NAME_LOC ,(SELECT COD2.TEXT1 FROM ICOMCOD2 COD2 WHERE COD2.CODE=LUSR.DEPARTMENT AND COMPANY_CODE='KRKORE0001' AND TYPE='C001' )DEPARTMENT , ROW_NUMBER() OVER (PARTITION BY NTS.ISSUE_ID ORDER BY MAP.ACCNO, MAP.ACCSEQ) ISSUE_CNT , NTS.GROUP_KEY AS NTS_GROUP_KEY , MAP.ISSUE_ID AS MAP_ISSUE_ID FROM ZDTV3T_NTS NTS, TACCOUNT_TAX_MAPPING MAP, ICOMLUSR LUSR WHERE 1=1 AND NTS.ISSUE_ID = MAP.ISSUE_ID(+) AND LUSR.COM_CODE(+)='KRKORE0001' AND LUSR.STATUS(+) <> 'D' AND LUSR.OFFICE_YN IS NULL AND LUSR.LEGACY_USER_ID(+) IS NOT NULL AND LUSR.EMAIL(+) = DECODE(NTS.ARAP,'AR',REPLACE(NTS.SU_EMAIL,'kolon.com','koreab2b.com'), 'AP',REPLACE(NTS.IP_EMAIL1,'kolon.com','koreab2b.com')) AND NTS.ISSUE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND NTS.ARAP = #{st_arap}
AND LUSR.USER_ID = #{st_add_user_id}
AND LUSR.DEPARTMENT = #{st_user_dept}
AND NTS.IP_ID LIKE #{st_ip_id}||'%'
AND NTS.IP_NAME LIKE #{st_ip_name}||'%'
AND NTS.IP_EMAIL1 LIKE #{st_ip_email}||'%'
AND NTS.SU_ID LIKE #{st_su_id}||'%'
AND NTS.SU_NAME LIKE #{st_su_name}||'%'
AND NTS.SU_EMAIL LIKE #{st_su_email}||'%'
AND MAP.ACCNO = #{st_accno}
AND NTS.ISSUE_ID = #{st_issue_id}
AND MAP.ISSUE_ID IS NOT NULL AND NTS.GROUP_KEY IS NULL
AND MAP.ISSUE_ID IS NULL AND NTS.GROUP_KEY IS NULL
AND NTS.GROUP_KEY IS NOT NULL
) WHERE ISSUE_CNT = 1 ORDER BY ARAP, SU_ID, IP_ID

